body { font: 16px system-ui; padding: 24px; }
:root { --accent: oklch(55% 0.2 255); }
.notice { max-width: 360px; padding: 20px; border-radius: 14px; background: color-mix(in oklch, var(--accent) 12%, white); }
.notice button { color: white; background: var(--accent); border: 0; border-radius: 8px; padding: 8px 12px; }
.notice p { color: #334155; }
